def _populate_matricules(apps, schema_editor):
    """Assign a unique EMP-YYYY-NNNN matricule to every employee that lacks one."""
    Employee = apps.get_model('personnel', 'Employee')
    year = timezone.now().year
    prefix = f"EMP-{year}-"

    with transaction.atomic():
        # Determine the next available sequence number for this year
        last = (
            Employee.objects.select_for_update()
            .filter(matricule__startswith=prefix)
            .order_by('matricule')
            .last()
        )
        sequence = int(last.matricule.split('-')[-1]) + 1 if last else 1

        employees_to_update = []
        for employee in Employee.objects.filter(matricule='').order_by('id'):
            employee.matricule = f"{prefix}{sequence:04d}"
            sequence += 1
            employees_to_update.append(employee)

        if employees_to_update:
            Employee.objects.bulk_update(employees_to_update, ['matricule'])


